result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "stoich.py", "content": """"Stoichiometry and limiting reagent calculator."""

import re

ATOMIC_WEIGHTS = {
    "H": 1.008,
    "C": 12.011,
    "N": 14.007,
    "O": 15.999,
}


def molar_mass(formula):
    """Compute molar mass of a formula like 'NH3', 'H2O', 'CO2'."""
    total = 0.0
    for element, count in re.findall(r"([A-Z][a-z]?)(\d*)", formula):
        if not element:
            continue
        total += ATOMIC_WEIGHTS[element] * (int(count) if count else 1)
    return total


def parse_side(side):
    """Parse one side of an equation into {species: coefficient}."""
    species = {}
    for term in side.split("+"):
        term = term.strip()
        m = re.match(r"^(\d+)\s*(.+)$", term)
        if m:
            coef, formula = int(m.group(1)), m.group(2).strip()
        else:
            coef, formula = 1, term
        species[formula] = species.get(formula, 0) + coef
    return species


def parse_equation(equation):
    """Parse 'N2 + 3 H2 -> 2 NH3' into ({reactants}, {products})."""
    lhs, rhs = equation.split("->")
    return parse_side(lhs), parse_side(rhs)


def solve(equation, amounts, product):
    """Given a balanced equation string, gram amounts of reactants, and a
    product name, return a dict with the limiting reagent, theoretical yield
    in grams of the product, and leftover grams of each excess reactant."""
    reactants, products = parse_equation(equation)

    if product not in products:
        raise ValueError(f"Unknown product: {product}")

    moles = {}
    for name, grams in amounts.items():
        if name not in reactants:
            raise ValueError(f"Unknown reactant: {name}")
        if grams < 0:
            raise ValueError(f"Negative amount for {name}")
        moles[name] = grams / molar_mass(name)

    # Extent of reaction each reactant could support (mol reaction).
    extents = {name: mol / coef for name, mol, coef in
               ((n, moles[n], reactants[n]) for n in moles)}
    limiting = min(extents, key=extents.get)
    extent = extents[limiting]

    yield_grams = extent * products[product] * molar_mass(product)

    leftovers = {}
    for name in amounts:
        consumed = extent * reactants[name]
        leftover_mol = max(moles[name] - consumed, 0.0)
        leftovers[name] = leftover_mol * molar_mass(name)

    return {
        "limiting_reagent": limiting,
        "theoretical_yield_g": yield_grams,
        "leftover_g": leftovers,
    }
"})
